package com.saludintegral.medico.controller;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import jakarta.validation.Valid;import java.util.*;import com.saludintegral.medico.model.HorarioMedico;import com.saludintegral.medico.dto.HorarioRequest;import com.saludintegral.medico.services.HorarioService;@RestController @RequestMapping("/api/horarios")public class HorarioController{final HorarioService s;public HorarioController(HorarioService s){this.s=s;}@GetMapping public List<HorarioMedico> all(){return s.all();}@GetMapping("/{id}")public HorarioMedico get(@PathVariable Long id){return s.get(id);}@PostMapping public ResponseEntity<HorarioMedico> create(@Valid @RequestBody HorarioRequest x){return ResponseEntity.status(201).body(s.save(x));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
